/**
 * Ground-truth XMap parity — the safety net the round-trip test couldn't be.
 *
 * `roundtrip.test.js` and `omap-from-map-snapshot.test.js` both compare
 * panmap's output against ITSELF (a second read cycle, or a golden snapshot
 * generated by the same writer). They pass even when the writer drops or
 * mangles an attribute in a way the reader can't tell was ever there —
 * because a symmetric read/write loss is invisible to a read/write test.
 *
 * This test compares against the Mapper-authored source .xmap directly. For
 * every symbol in the fixture, it asserts that panmap's writer emits the
 * same symbol shape Mapper originally wrote. Attribute-level differences
 * are enumerated so the failure output pinpoints which line-symbol /
 * point-symbol / area-symbol field the writer is dropping.
 *
 * The comparison is *semantic*, not byte-identical:
 *   - attribute order is ignored (XML attrs are unordered),
 *   - whitespace-only text nodes are ignored,
 *   - symbol IDs are ignored (panmap re-numbers on write),
 *   - Mapper-omitted attributes matching a stable set of writer defaults
 *     don't fail (so "writer emitted mid_symbol_placement=0 while Mapper
 *     omitted it" isn't reported when 0 is the format default).
 *
 * @typedef {import('../node_modules/ava/types/test-fn').ExecutionContext} ExecutionContext
 */
import test from 'ava'
import fs from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { XMLParser } from 'fast-xml-parser'
import { readOmap, mapToOmapXml } from './helpers/omap.js'
import omapFileToMap from '../src/formats/omap/reader/to-panmap.ts'
import { gitmap } from '../src/index.ts'
import { fixtureFile } from './helpers/fixtures.js'
import { parityScore } from './helpers/parity-score.js'

// Every `.xmap` in the corpus, one per map (latest revision — an older
// revision of the same map exercises the same writer paths). This test
// started narrow on bottle-lake bc98714, the fixture that surfaced the
// symbol-writer drift in prod; it now covers the same set as the other
// three parity suites so a regression can't hide in an untested map.
const FIXTURES = [
  { name: 'ara', file: 'ara-c122f2d.xmap' },
  { name: 'bottle-lake-bc98714', file: 'bottle-lake-bc98714.xmap' },
  { name: 'butlers-bush', file: 'butlers-bush-bdc004d.xmap' },
  { name: 'castle-hill-village', file: 'castle-hill-village-22e8154.xmap' },
  { name: 'hillmorton', file: 'hillmorton-6275ebc.xmap' },
  { name: 'kura-tawhiti', file: 'kura-tawhiti-0b613b2.xmap' },
  { name: 'laidmore', file: 'laidmore-0f52898.xmap' },
  { name: 'leithfield', file: 'leithfield-69f0423.xmap' },
  { name: 'lincoln-university', file: 'lincoln-university-d44e8ce.xmap' },
  {
    name: 'nga-puna-wai-canterbury-park',
    file: 'nga-puna-wai-canterbury-park-beba671.xmap',
  },
  { name: 'orua-paeroa', file: 'orua-paeroa-bf353d6.xmap' },
  { name: 'rangiora', file: 'rangiora-7545c63.xmap' },
  {
    name: 'university-of-canterbury',
    file: 'university-of-canterbury-f3dd92a.xmap',
  },
  { name: 'woodend', file: 'woodend-4a10570.xmap' },
]

// The two round-trip paths we assert against source parity. `direct` is
// xmap → PanMap → xmap. `via-gitmap` reads the xmap, writes it as a
// gitmap package, reads that back, and writes xmap — the pipeline
// mapwall uses (its `convertMap` downloads .omap from the gitmap tree).
// A drift that only shows up on `via-gitmap` narrows the bug to
// gitmap read/write; a drift on both narrows it to xmap writer.
const CYCLES = [
  {
    name: 'direct',
    async regenerate(map) {
      return mapToOmapXml(map)
    },
  },
  {
    name: 'via-gitmap',
    async regenerate(map) {
      const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'gm-cycle-'))
      const pkg = path.join(dir, 'm.gitmap')
      await gitmap.write(map, pkg, { overwrite: true })
      const roundTripped = await gitmap.read(pkg)
      return mapToOmapXml(roundTripped)
    },
  },
]

// Attribute names whose value we never enforce. Writer-side renumbering
// of symbol IDs is intentional (panmap re-emits ids in registration
// order); it doesn't affect what Mapper renders. Same for `name`, which
// is cosmetic display text. `code` is normalised separately in
// `codesEquivalent` because "101.0" and "101" collide on the same
// canonical form and Mapper's reader accepts either.
const IGNORED_ATTRS = new Set(['@id', '@name', '@code'])

// XMap attributes where Mapper's omission is equivalent to the writer
// emitting a specific default value. Keyed by immediate parent element
// name. When Mapper omits and panmap emits exactly one of these values,
// don't flag it — the two spellings are semantically equal.
const OMITTABLE_DEFAULTS = new Map([
  ['line_symbol.mid_symbol_placement', '0'],
  ['line_symbol.suppress_dash_symbol_at_ends', 'false'],
  ['line_symbol.dashed', 'false'],
  ['line_symbol.mid_symbols_per_spot', '1'],
  ['line_symbol.mid_symbol_distance', '0'],
  ['point_symbol.rotatable', 'false'],
  ['text_symbol.rotatable', 'false'],
  ['symbol.code', ''],
  ['symbol.name', ''],
])

function makeXmlParser() {
  return new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: '@',
    removeNSPrefix: true,
    allowBooleanAttributes: true,
    processEntities: true,
    // Keep child element order so we can compare structure — fast-xml-parser
    // collapses same-named siblings into arrays by default, which is what
    // we want for `<symbol>`, `<pattern>` etc.
    preserveOrder: false,
  })
}

function parseXml(xml) {
  return makeXmlParser().parse(xml)
}

// Walk the parsed XML tree until we find a `.symbols` container. Mapper's
// XMap nests `<symbols>` under `<map><barrier>[0]`, and older Mapper builds
// vary the wrapper depth. Walking finds it regardless.
function findSymbolsContainer(node) {
  if (!node || typeof node !== 'object') return null
  if (node.symbols) return node.symbols
  for (const v of Object.values(node)) {
    if (Array.isArray(v)) {
      for (const item of v) {
        const found = findSymbolsContainer(item)
        if (found) return found
      }
    } else if (typeof v === 'object' && v !== null) {
      const found = findSymbolsContainer(v)
      if (found) return found
    }
  }
  return null
}

// Extract every top-level `<symbol>` node keyed by its `code` attribute.
// The code is the ISOM number ("101", "413.1", "416.0", …) — stable across
// re-numbering, unlike the raw @id.
function symbolsByCode(root) {
  const container = findSymbolsContainer(root)
  const raw = container?.symbol
  const list = Array.isArray(raw) ? raw : raw ? [raw] : []
  const byCode = new Map()
  for (const s of list) {
    const code = String(s?.['@code'] ?? '')
    if (!code) continue
    // Normalise "101" and "101.0" to the same key — Mapper's UI drops the
    // trailing ".0" for whole-number ISOM codes; panmap re-emits without it.
    // Compare by the numeric-equivalent key so "101" ↔ "101.0" line up.
    const key = code.replace(/\.0$/, '')
    if (!byCode.has(key)) byCode.set(key, s)
  }
  return byCode
}

// The set of child-element keys we compare, in a fixed order. Attribute
// keys ("@…") on the same node are compared unconditionally. Element keys
// not in this list are ignored (e.g. `@id`, `@name` at the top level are
// noise for symbol identity).
const COMPARED_CHILDREN = new Set([
  'line_symbol',
  'point_symbol',
  'area_symbol',
  'text_symbol',
  'combined_symbol',
  'element',
  'mid_symbol',
  'start_symbol',
  'end_symbol',
  'dash_symbol',
  'corner_symbol',
  'border',
  'pattern',
  'symbol',
])

// Diff two subtrees rooted at `path` (e.g. "<symbol 101>.line_symbol").
// The immediate parent-element name (`parentTag`) is threaded through so
// OMITTABLE_DEFAULTS can be keyed on the container element (e.g.
// `line_symbol.dashed`), not the whole path from the root.
function diffNode(expected, actual, path, parentTag, out) {
  out.comparisons = (out.comparisons || 0) + 1
  if (expected == null && actual == null) return
  if (typeof expected !== 'object' || typeof actual !== 'object') {
    if (String(expected) !== String(actual)) {
      out.push({ path, expected, actual })
    }
    return
  }

  const allKeys = new Set([
    ...Object.keys(expected || {}),
    ...Object.keys(actual || {}),
  ])

  for (const key of allKeys) {
    if (key.startsWith('@')) {
      if (IGNORED_ATTRS.has(key)) continue
      const attrName = key.slice(1)
      const expVal = expected?.[key]
      const actVal = actual?.[key]
      const defaultKey = `${parentTag}.${attrName}`
      if (expVal === undefined) {
        if (OMITTABLE_DEFAULTS.get(defaultKey) === String(actVal)) continue
        out.push({
          path: `${path}[@${attrName}]`,
          expected: '(omitted)',
          actual: actVal,
        })
      } else if (actVal === undefined) {
        if (OMITTABLE_DEFAULTS.get(defaultKey) === String(expVal)) continue
        out.push({
          path: `${path}[@${attrName}]`,
          expected: expVal,
          actual: '(omitted)',
        })
      } else if (String(expVal) !== String(actVal)) {
        out.push({
          path: `${path}[@${attrName}]`,
          expected: expVal,
          actual: actVal,
        })
      }
      continue
    }

    if (!COMPARED_CHILDREN.has(key)) continue

    const expChildren = toArray(expected?.[key])
    const actChildren = toArray(actual?.[key])
    if (expChildren.length !== actChildren.length) {
      out.push({
        path: `${path}.${key}[]`,
        expected: `${expChildren.length} node(s)`,
        actual: `${actChildren.length} node(s)`,
      })
    }
    const n = Math.max(expChildren.length, actChildren.length)
    for (let i = 0; i < n; i++) {
      diffNode(
        expChildren[i] ?? null,
        actChildren[i] ?? null,
        `${path}.${key}[${i}]`,
        key,
        out,
      )
    }
  }
}

function toArray(v) {
  if (v == null) return []
  return Array.isArray(v) ? v : [v]
}

// Human-readable diff report: one line per attribute mismatch, grouped by
// symbol so the failure output points at "symbol 101, <line_symbol>,
// dash_length" rather than a dump of the whole map.
function formatDiff(mismatches) {
  const groups = new Map()
  for (const m of mismatches) {
    const symbolPath = m.path.match(/^<symbol [^>]+>/)?.[0] ?? '<root>'
    if (!groups.has(symbolPath)) groups.set(symbolPath, [])
    groups
      .get(symbolPath)
      .push(
        `  ${m.path.slice(symbolPath.length + 1) || '(this node)'}: expected=${JSON.stringify(
          m.expected,
        )} actual=${JSON.stringify(m.actual)}`,
      )
  }
  const lines = []
  for (const [sym, entries] of groups) {
    lines.push(sym)
    lines.push(...entries.slice(0, 6))
    if (entries.length > 6)
      lines.push(`  … ${entries.length - 6} more mismatches in this symbol`)
  }
  return lines.join('\n')
}

for (const { name, file } of FIXTURES) {
  for (const cycle of CYCLES) {
    test(`xmap ground-truth parity (${cycle.name}): ${name}`, async t => {
      const src = await fs.readFile(fixtureFile(file), 'utf-8')
      const map = omapFileToMap(await readOmap(src))
      const regenerated = await cycle.regenerate(map)

      const expected = parseXml(src)
      const actual = parseXml(regenerated)

      const expectedByCode = symbolsByCode(expected)
      const actualByCode = symbolsByCode(actual)

      const mismatches = []

      // Symbols present in one and not the other are their own class of
      // failure — flag those before diving into per-symbol attribute diffs.
      for (const code of expectedByCode.keys()) {
        if (!actualByCode.has(code)) {
          mismatches.push({
            path: `<symbol ${code}>`,
            expected: '(present)',
            actual: '(missing)',
          })
        }
      }
      for (const code of actualByCode.keys()) {
        if (!expectedByCode.has(code)) {
          mismatches.push({
            path: `<symbol ${code}>`,
            expected: '(missing)',
            actual: '(present)',
          })
        }
      }

      for (const [code, expSymbol] of expectedByCode) {
        const actSymbol = actualByCode.get(code)
        if (!actSymbol) continue
        diffNode(expSymbol, actSymbol, `<symbol ${code}>`, 'symbol', mismatches)
      }

      if (mismatches.length === 0) {
        t.pass()
        return
      }
      t.fail(
        `${parityScore({
          mismatches,
          symbolCount: expectedByCode.size,
          fieldCount: mismatches.comparisons,
          what: "panmap's regenerated xmap",
          against: 'the Mapper-authored source',
        })}\n${formatDiff(mismatches.slice(0, 40))}`,
      )
    })
  }
}
